using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Boss 核心 — 挂在有 EnemyCore 的 GameObject 上，管理阶段切换和技能调度。
/// 使用 EnemySkillManager 管理技能，不自行维护技能列表。
/// skillLibrary 取自 EnemyConfig.skillLibrary。
/// </summary>
[RequireComponent(typeof(EnemyCore))]
public class BossCore : MonoBehaviour
{
    [Header("阶段配置")]
    [Tooltip("按健康阈值升序排列的阶段 (Phase1 在前, Phase2 在后)")]
    [SerializeField] private BossPhaseData[] _phases;

    [Header("调试")]
    [SerializeField] private int _currentPhaseIndex;
    [SerializeField] private float _nextSkillTime;

    private EnemyCore _enemyCore;
    private EnemyStats _health;
    private EnemyMovement _movement;
    private EnemySkillManager _skillManager;
    private SkillLibrary _skillLibrary;
    private BossPhaseData CurrentPhase => _phases != null && _currentPhaseIndex < _phases.Length
        ? _phases[_currentPhaseIndex] : null;

    private void Awake()
    {
        _enemyCore = GetComponent<EnemyCore>();
        _health = GetComponent<EnemyStats>();
        _movement = GetComponent<EnemyMovement>();
        _skillManager = GetComponent<EnemySkillManager>();

        if (_phases == null || _phases.Length == 0)
        {
            Debug.LogWarning("BossCore: 未配置 _phases，Boss 将无法切换阶段");
            return;
        }
    }

    private void Start()
    {
        _skillLibrary = _enemyCore.config != null ? _enemyCore.config.skillLibrary : null;
        if (_skillLibrary == null)
            Debug.LogWarning("BossCore: EnemyConfig.skillLibrary 未配置");

        LoadPhaseSkills(0);

        // 显示 Boss 血条（屏幕顶部）
        if (BossHealthBar.Instance != null && _health != null)
            BossHealthBar.Instance.Show(_enemyCore.config != null ? _enemyCore.config.displayName : "Boss", _health.MaxHealth);
    }

    private void OnEnable()
    {
        if (_health != null)
            _health.OnHealthChanged += OnHealthChanged;
    }

    private void OnDisable()
    {
        if (_health != null)
            _health.OnHealthChanged -= OnHealthChanged;
    }

    private void OnDestroy()
    {
        // Boss 死亡/销毁 → 隐藏血条
        if (BossHealthBar.Instance != null)
            BossHealthBar.Instance.Hide();
    }

    private void Update()
    {
        if (_enemyCore.IsDead) return;

        float dt = Time.deltaTime;

        // Tick skill cooldowns via EnemySkillManager
        if (_skillManager != null)
            _skillManager.TickCooldowns(dt);

        TryCastSkill();
    }

    // ==================== 阶段切换 ====================

    private void OnHealthChanged(float currentHp, float maxHp)
    {
        // 更新 Boss 血条
        if (BossHealthBar.Instance != null)
            BossHealthBar.Instance.UpdateHealth(currentHp, maxHp);

        float ratio = maxHp > 0 ? currentHp / maxHp : 1f;

        for (int i = _phases.Length - 1; i > _currentPhaseIndex; i--)
        {
            if (ratio <= _phases[i].healthThreshold)
            {
                EnterPhase(i);
                return;
            }
        }
    }

    private void EnterPhase(int phaseIndex)
    {
        _currentPhaseIndex = phaseIndex;
        var newPhase = CurrentPhase;
        if (newPhase == null) return;

        Debug.Log($"BossCore: 进入 {newPhase.phaseName}");

        LoadPhaseSkills(phaseIndex);

        if (_health != null)
        {
            float baseSpeed = _health.ChaseSpeed;
            _health.ChaseSpeed = baseSpeed * newPhase.moveSpeedMult;
        }

        _nextSkillTime = Time.time + 0.5f;
    }

    // ==================== 技能管理（通过 EnemySkillManager） ====================

    private void LoadPhaseSkills(int phaseIndex)
    {
        if (_phases == null || phaseIndex >= _phases.Length || _skillManager == null || _skillLibrary == null) return;
        var phase = _phases[phaseIndex];
        if (phase.skills == null) return;

        var ids = new List<string>();
        foreach (var sd in phase.skills)
            if (sd != null) ids.Add(sd.skillId);

        _skillManager.LoadSkills(_skillLibrary, ids.ToArray());
    }

    private void TryCastSkill()
    {
        var phase = CurrentPhase;
        if (phase == null || _skillManager == null) return;
        if (Time.time < _nextSkillTime) return;

        var ready = _skillManager.GetReadySkill();
        if (ready == null) return;

        Vector2 dir = _enemyCore.PlayerTarget != null
            ? (_enemyCore.PlayerTarget.position - transform.position).normalized
            : Vector2.down;

        ready.TryCast(_enemyCore, dir);
        _nextSkillTime = Time.time + phase.skillInterval;
    }
}

using UnityEngine;

/// <summary>
/// Boss 张嘴冲刺状态（巨噬细胞 Boss 等）— 检测玩家是否在同一行/同一列：
/// 1) 对齐（同行 |dy| 或同列 |dx| 小于阈值）→ 朝该轴方向释放冲刺技能（SlideSkillEffect 冲撞）；
/// 2) 冲刺期间由 SlideRuntime 处理位移与碰撞；
/// 3) 冲刺结束后切回 ChaseState；不对齐则切回 ChaseState 追击。
/// 与 AxialSprayState（原地喷射）不同：本状态朝轴向冲刺移动。
/// </summary>
public class BossLungeState : EnemyStateBase
{
    /// <summary>是否已触发冲刺</summary>
    private bool _lunging;

    /// <summary>冲刺是否已结束（检测 SlideRuntime 从 active 恢复）</summary>
    private bool _sawSlideEnd;

    public BossLungeState(EnemyCore core) : base(core) { }

    public override void Enter()
    {
        Core.Movement?.Stop();
        _lunging = false;
        _sawSlideEnd = false;
    }

    public override void Tick()
    {
        if (Core.PlayerTarget == null || Core.Health == null)
        {
            Core.StateMachine.ChangeState(new IdleState(Core));
            return;
        }

        // ── 冲刺锁定阶段 ──
        if (_lunging)
        {
            var slide = Core.GetComponent<SlideRuntime>();
            if (slide != null && slide.IsActive)
            {
                _sawSlideEnd = true;   // 冲刺中
            }
            else if (_sawSlideEnd)
            {
                // 冲刺已结束
                Core.StateMachine.ChangeState(new ChaseState(Core));
                return;
            }
            // 前摇阶段：SlideRuntime 尚未激活，继续等待
            return;
        }

        // ── 检测同行/同列对齐 ──
        Vector2 playerPos = Core.PlayerTarget.position;
        Vector2 myPos = Core.transform.position;
        float threshold = Core.config != null && Core.config.axialAlignThreshold > 0f
            ? Core.config.axialAlignThreshold
            : 0.6f;

        bool aligned = Mathf.Abs(playerPos.x - myPos.x) <= threshold
                    || Mathf.Abs(playerPos.y - myPos.y) <= threshold;

        if (!aligned)
        {
            Core.StateMachine.ChangeState(new ChaseState(Core));
            return;
        }

        // ── 对齐 → 尝试冲刺（朝玩家所在轴向） ──
        if (Core.SkillManager != null && Core.SkillManager.TryCastSkill(0, Core, Core.GetTargetDirection()))
        {
            _lunging = true;
        }
        // 技能冷却中则待命（保持对齐，不移动）
        else
        {
            Core.Movement?.Stop();
        }
    }
}

using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Boss 血条 — 屏幕顶部显示 Boss 血条（含名字）。
/// 单例，Boss 出生时由 BossCore 触发显示，Boss 死亡时隐藏。
/// 用静态 BossHealthBar.Instance 访问，BossCore 在 Start/OnHealthChanged 时驱动。
/// </summary>
public class BossHealthBar : MonoBehaviour
{
    public static BossHealthBar Instance { get; private set; }

    [Header("引用")]
    [SerializeField] private GameObject _panel;
    [SerializeField] private Image _fillImage;
    [SerializeField] private Text _nameText;

    private float _maxHp = 1f;
    private bool _visible;

    private void Awake()
    {
        Instance = this;
        SetVisible(false);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    /// <summary>显示 Boss 血条并设置名字</summary>
    public void Show(string bossName, float maxHp)
    {
        _maxHp = Mathf.Max(maxHp, 1f);
        if (_nameText != null) _nameText.text = bossName;
        SetVisible(true);
    }

    /// <summary>更新血条（当前/最大）</summary>
    public void UpdateHealth(float currentHp, float maxHp)
    {
        if (maxHp > 0f) _maxHp = maxHp;
        float ratio = Mathf.Clamp01(currentHp / _maxHp);
        if (_fillImage != null) _fillImage.fillAmount = ratio;
    }

    /// <summary>隐藏 Boss 血条</summary>
    public void Hide()
    {
        SetVisible(false);
    }

    private void SetVisible(bool v)
    {
        _visible = v;
        if (_panel != null) _panel.SetActive(v);
    }
}

using UnityEngine;

/// <summary>
/// 泛用滑移/冲刺技能效果 — 朝移动方向冲刺位移一段距离，期间无敌。
/// 玩家朝 WASD 移动方向（无输入则朝鼠标方向）；敌人随机方向。
/// 可选"卷起敌人"：位移途中卷起途经的敌人（吸附跟随 + 命中伤害），
/// 被卷起的敌人撞到墙/障碍后受到二次伤害并释放。
/// 可选"爆发冲击"：自动朝最近敌人突进，命中后周身释放气浪推开周边敌方。
/// 所有能力参数驱动：距离、速度、无敌时长、拖影材质、卷起/爆发开关均可配置。
/// 右键 -> Create -> Game -> Skill Effect -> Slide
/// </summary>
[CreateAssetMenu(fileName = "SlideEffect", menuName = "Game/Skill Effect/Slide")]
public class SlideSkillEffect : SkillEffectBase
{
    [Header("滑移配置")]
    [Tooltip("位移距离")]
    [SerializeField] private float _distance = 3f;
    [Tooltip("滑移速度（单位/秒）")]
    [SerializeField] private float _speed = 18f;
    [Tooltip("滑移期间无敌时长（秒）")]
    [SerializeField] private float _immuneDuration = 0.5f;
    [Tooltip("拖影材质（null=无拖影）")]
    [SerializeField] private Material _trailMaterial;

    [Header("卷起敌人（可选）")]
    [Tooltip("是否卷起途经的敌人")]
    [SerializeField] private bool _carryEnemies = false;
    [Tooltip("卷起检测半径")]
    [SerializeField] private float _carryRadius = 1f;
    [Tooltip("卷起时对敌人造成的伤害")]
    [SerializeField] private float _carryDamage = 20f;
    [Tooltip("卷起的敌人撞墙后的二次伤害")]
    [SerializeField] private float _wallDamage = 30f;
    [Tooltip("卷起的敌人是否无敌于其他伤害（跟随期间）")]
    [SerializeField] private bool _carriedInvincible = true;

    [Header("爆发冲击（可选）")]
    [Tooltip("自动朝最近的敌人方向突进（否则用移动/鼠标方向）")]
    [SerializeField] private bool _autoAimNearest = false;
    [Tooltip("命中敌人后周身释放气浪推开周边敌方（不卷走目标）")]
    [SerializeField] private bool _burstOnHit = false;
    [Tooltip("气浪半径")]
    [SerializeField] private float _burstRadius = 4f;
    [Tooltip("气浪推开力度（径向击退初速度）")]
    [SerializeField] private float _burstPushForce = 10f;
    [Tooltip("气浪视觉材质（可复用扩散波/气浪 shader 材质）")]
    [SerializeField] private Material _burstWaveMaterial;

    public override void Execute(ISkillCaster caster, Vector2 direction,
                                  float damageMultiplier, Projectile.OwnerType ownerType)
    {
        // 已有滑移在进行中则不重复触发
        var existing = caster.CasterTransform.GetComponent<SlideRuntime>();
        if (existing != null && existing.IsActive) return;

        var slide = caster.CasterTransform.gameObject.AddComponent<SlideRuntime>();
        slide.Activate(caster, _distance, _speed, _immuneDuration, _trailMaterial);

        // 卷起能力配置
        if (_carryEnemies)
        {
            slide.EnableCarrying(_carryRadius, _carryDamage * damageMultiplier,
                _wallDamage, _carriedInvincible, ownerType);
        }

        // 爆发冲击配置（自动锁敌 + 命中释放气浪）
        if (_autoAimNearest || _burstOnHit)
        {
            slide.EnableBurst(_autoAimNearest, _burstOnHit, _burstRadius,
                _burstPushForce, _burstWaveMaterial, ownerType);
        }
    }
}

